"""Generate the two buildless project introductions; no application APIs or signup."""
from pathlib import Path
from html import escape
from shutil import copyfile

seo = {
    'yaqeen': ('Yaqeen — Islamic Faith, Dua & Community | Coming Soon', 'Discover Yaqeen, a planned Islamic faith and community platform for daily dua, adhkar, reflection, and spiritual connection. Coming soon.'),
    'afrimed': ('Afrimed — Healthcare Technology for Africa | Coming Soon', 'Discover Afrimed, a healthcare project exploring health technology, connections to care, and community support across Africa. Coming soon.'),
}

root = Path(__file__).resolve().parents[1] / 'site'
projects = [dict(slug='yaqeen', name='Yaqeen', domain='yaqeen-w.tech', icon='yaqeen-logo.svg', label='Faith. Reflection. Connection.', heading='A little more peace.<br>A deeper <em>connection.</em>', lead='A space being built around Islamic faith, daily remembrance, and a caring community. Yaqeen brings a thoughtful vision for spiritual life on mobile and web.', visual='<div class="arabic" lang="ar" dir="rtl">يقين</div>', caption='A moment to reconnect', floating='Rooted in faith.<br>Made for the moments of everyday life.', section='A thoughtful home for your spiritual journey.', features=[('Daily remembrance','A planned dua and adhkar library, with Arabic text, translations, and reminders to make room for remembrance.'),('A caring community','A vision for conversations around faith, prayer, gratitude, and patience, with care at the heart of the experience.'),('Guidance with care','Exploring source-grounded Islamic learning and spiritual support, with content review before public release.')], story='Yaqeen means certainty. The project is taking shape as a calm place to learn, reflect, and connect through Islamic teachings.', owner='Zaineb Marzaq', quote='Room to reflect.<br>Reasons to connect.<br>Faith in the everyday.', faq=[('Can I use Yaqeen yet?','Not yet. This is an introduction to the project. Public registration and the application are not open here.'),('What is being built?','The vision includes an Islamic community, a dua and adhkar library, daily reminders, and thoughtfully reviewed guidance. These are planned areas, not a list of services available today.'),('When will it launch?','A public launch date has not been announced. This website will share the next chapter when it is ready.')]),dict(slug='afrimed',name='Afrimed',domain='health.afrimed.space',icon='afrimed-icon.png',label='Health. Access. Community.',heading='Closer to care.<br>More <em>possibility.</em>',lead='A healthcare project focused on Africa, exploring how technology can make health information, care connections, and community support more accessible.',visual='<div class="cross" aria-hidden="true">+</div>',caption='Care starts with connection',floating='Technology with a human purpose.<br>A more connected path to healthcare.',section='A vision for more approachable healthcare.',features=[('Health technology','Exploring AI-assisted medical image analysis as part of a broader healthcare experience, with responsible development at its core.'),('Connections to care','Developing ways to discover healthcare providers and bring people closer to useful care information.'),('Community support','Working toward medical-aid transparency and a place to follow health information and personal records.')],story='Afrimed brings together health technology and community care with a focus on healthcare access across Africa. Its next chapter is being built with that purpose in mind.',owner='Abderrahmane Benaamar',quote='Better connections.<br>More accessible information.<br>People at the centre.',faq=[('Is Afrimed available now?','The public experience is coming soon. This page introduces the project and its direction; it does not provide clinical services.'),('Can I upload scans or get a diagnosis here?','No. This website does not accept medical records, analyse scans, or provide a diagnosis. For medical advice, speak with a qualified healthcare professional.'),('When will the project launch?','There is no announced public launch date. More details will be shared here as the project develops.')])]
for p in projects:
    folder=root/p['slug']; folder.mkdir(exist_ok=True)
    copyfile(root/p['icon'], folder/p['icon'])
    copyfile(root/'projects.css', folder/'projects.css')
    features=''.join(f'<article class="feature"><span class="number">0{i}</span><h3>{escape(t)}</h3><p>{escape(d)}</p></article>' for i,(t,d) in enumerate(p['features'],1))
    faq=''.join(f'<details><summary>{escape(q)}</summary><p>{escape(a)}</p></details>' for q,a in p['faq'])
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{p['name']} — Coming soon</title><meta name="description" content="{escape(p['lead'])}"><meta name="theme-color" content="#173f38"><link rel="canonical" href="https://{p['domain']}/"><meta property="og:title" content="{p['name']} — Coming soon"><meta property="og:description" content="{escape(p['lead'])}"><meta property="og:type" content="website"><meta property="og:url" content="https://{p['domain']}/"><link rel="icon" href="/{p['icon']}"><link rel="stylesheet" href="/projects.css"></head>
<body class="{p['slug']}"><a class="skip" href="#main">Skip to content</a><div class="wrap"><header><a class="brand" href="/"><img src="/{p['icon']}" alt="" width="44" height="44">{p['name']}</a><nav aria-label="Main navigation"><a href="#vision">The vision</a><a href="#questions">Questions</a></nav></header><main id="main"><section class="hero"><div><span class="status">Coming soon</span><p class="eyebrow">{p['label']}</p><h1>{p['heading']}</h1><p class="lead">{p['lead']}</p><a class="button" href="#vision">Discover the vision ↗</a><p class="note">Thoughtfully taking shape. A public launch date is still to come.</p></div><div class="scene"><div class="scene-center"><img src="/{p['icon']}" alt="{p['name']} project artwork" width="130" height="130">{p['visual']}<p class="scene-caption">{p['caption']}</p></div><div class="floating">{p['floating']}</div></div></section><section class="section" id="vision"><div class="section-title"><p class="eyebrow">01 / The vision</p><h2>{p['section']}</h2></div><p class="note">The following describes the project's direction. Features are in development and may evolve before launch.</p><div class="features">{features}</div></section><section class="section story"><div><p class="eyebrow">02 / The story</p><h2>Built with intention.</h2><p>{p['story']}</p><p>A project by {p['owner']}, introduced alongside the independent projects at <a href="https://afrimed.space/">Afrimed Space ↗</a>.</p></div><div class="statement">{p['quote']}</div></section><section class="section" id="questions"><div class="section-title"><p class="eyebrow">03 / A few answers</p><h2>Before the next chapter.</h2></div>{faq}</section></main><footer><span>© 2026 {p['name']} · Coming soon</span><a href="https://afrimed.space/">Explore Afrimed Space ↗</a></footer></div></body></html>'''
    title, description = seo[p['slug']]
    html = html.replace(f"{p['name']} — Coming soon", escape(title))
    html = html.replace(f'content="{escape(p["lead"])}"', f'content="{escape(description)}"')
    html = html.replace('</head>', f'''<meta name="robots" content="index, follow, max-image-preview:large">
<meta property="og:site_name" content="{p['name']}"><meta property="og:locale" content="en_US">
<meta property="og:image" content="https://{p['domain']}/social-preview.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="{p['name']} — {p['label']} Coming soon">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title)}"><meta name="twitter:description" content="{escape(description)}"><meta name="twitter:image" content="https://{p['domain']}/social-preview.png"><meta name="twitter:image:alt" content="{p['name']} — {p['label']} Coming soon"></head>''')
    # Google supports WebSite microdata; no executable script or CSP relaxation.
    html = html.replace(f'<body class="{p["slug"]}">', f'<body class="{p["slug"]}" itemscope itemtype="https://schema.org/WebSite"><meta itemprop="name" content="{p["name"]}"><link itemprop="url" href="https://{p["domain"]}/"><meta itemprop="description" content="{escape(description)}"><meta itemprop="inLanguage" content="en">')
    (folder/'index.html').write_text(html,encoding='utf-8')
    (folder/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: https://{p["domain"]}/sitemap.xml\n')
    (folder/'sitemap.xml').write_text(f'<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>https://{p["domain"]}/</loc></url></urlset>')
print('Generated Afrimed and Yaqeen coming-soon pages')
